## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/meniscusRepairLogic.ts`

```typescript
export type TearLocation = "medial" | "lateral" | "both";
export type TearPattern = "longitudinal" | "radial" | "horizontal" | "complex" | "bucket-handle";

export type MeniscusRepairInput = {
  age: string; affectedSide: string; tearLocation: string; tearPattern: string;
  symptomDurationMonths: string; painScore: string; symptoms: string[];
  conservativeTherapyMonths: string; conservativeTherapies: string[];
  tearCharacteristics: string[];
  acuteTear: boolean; activeSports: boolean; osteoarthritis: boolean;
  activeInfection: boolean; severeOA: boolean;
};

export type COR = "I" | "IIa" | "IIb" | "III";

export function getCORLabel(cor: COR): string {
  return { I: "Class I — Recommended", IIa: "Class IIa — Reasonable", IIb: "Class IIb — May Be Considered", III: "Class III — Not Recommended" }[cor];
}
export function getCORColor(cor: COR): string {
  return { I: "border-green-500 text-green-700", IIa: "border-blue-500 text-blue-700", IIb: "border-yellow-500 text-yellow-700", III: "border-red-500 text-red-700" }[cor];
}

export function assessMeniscusRepair(input: MeniscusRepairInput) {
  const conservMonths = parseFloat(input.conservativeTherapyMonths) || 0;
  const age = parseFloat(input.age) || 0;

  const contraindications: string[] = [];
  if (input.activeInfection) contraindications.push("Active knee infection — absolute contraindication");
  if (input.severeOA) contraindications.push("Severe knee osteoarthritis (bone-on-bone) — meniscectomy/repair unlikely to benefit; consider TKA");

  if (contraindications.length > 0) {
    return { recommendation: "Knee Arthroscopy Contraindicated", cor: "III" as COR, loe: "B", urgency: "Contraindicated", rationale: ["Contraindications identified."], contraindications, optimizationSteps: [] };
  }

  const rationale: string[] = [];
  const optimizationSteps: string[] = [];
  let cor: COR = "IIb";
  let urgency = "Elective";

  const isMechanical = input.symptoms.includes("locking") || input.symptoms.includes("giving-way");
  const isPeripheral = input.tearCharacteristics.includes("peripheral-zone");
  const isBucketHandle = input.tearPattern === "bucket-handle";
  const isComplex = input.tearPattern === "complex";

  if (isBucketHandle && isMechanical) {
    cor = "I"; urgency = "Urgent";
    rationale.push("Locked bucket-handle tear with mechanical symptoms — urgent arthroscopic intervention recommended");
    rationale.push("Delay risks irreversible cartilage damage from locked fragment");
  } else if (isMechanical && !isComplex && !input.osteoarthritis) {
    cor = "I"; urgency = "Appropriate";
    rationale.push("Mechanical symptoms (locking/giving way) with repairable tear pattern");
    rationale.push("Arthroscopic repair or meniscectomy recommended");
    if (isPeripheral && age < 50) rationale.push("Peripheral (vascular) zone tear in younger patient — repair preferred over meniscectomy");
  } else if (isComplex || input.osteoarthritis) {
    cor = "IIb"; urgency = "Limited Benefit Expected";
    rationale.push("Complex/degenerative tear or concurrent OA — evidence does not support arthroscopy over PT");
    rationale.push("AAOS and NEJM trials show no benefit of arthroscopy over PT for degenerative tears with OA");
    optimizationSteps.push("Continue PT and weight management as first-line treatment");
    optimizationSteps.push("Consider intraarticular injection for symptom relief");
  } else if (conservMonths < 3 && !isMechanical) {
    cor = "IIb"; urgency = "Continue Conservative Therapy";
    rationale.push("Non-mechanical tear without adequate conservative therapy trial");
    optimizationSteps.push("Continue PT for ≥3 months before considering surgery");
  } else {
    cor = "IIa"; urgency = "Reasonable";
    rationale.push("Symptomatic meniscal tear with adequate conservative therapy failure");
    rationale.push("Arthroscopy is reasonable in appropriate candidates");
  }

  if (input.activeSports && isPeripheral) optimizationSteps.push("Active athlete with peripheral tear — repair preferred to preserve meniscal function");

  return { recommendation: cor === "I" ? "Knee Arthroscopy Recommended" : cor === "IIa" ? "Arthroscopy Reasonable" : cor === "IIb" && urgency === "Urgent" ? "Urgent Arthroscopy" : "Continue Conservative Therapy", cor, loe: isBucketHandle ? "A" : "B", urgency, rationale, contraindications, optimizationSteps };
}
```


